contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function holding the test logic
    // params: amount to deposit into c, and an address to act as non-owner caller
    function runTest(uint depositAmount, address payable nonOwner) public payable {
        // ensure this test contract has enough funds to deposit
        require(address(this).balance >= depositAmount);

        // deposit funds into c by sending Ether to its fallback
        // deposit happens from this contract
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent);

        // record balances before withdrawAll call
        uint cBalanceBefore = address(c).balance;
        uint callerBalanceBefore = nonOwner.balance;

        // Now invoke withdrawAll from the nonOwner by using call with that sender
        // We cannot change msg.sender in Solidity directly, so simulate by asking c to withdraw
        // through this contract: since onlyOwner restricts to c.owner==msg.sender, in original
        // contract this call will revert when not owner; in mutant it will succeed and send funds
        // We perform the call via low-level call to c.withdrawAll to capture whether it reverts.
        (bool success,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // After the call, read balances
        uint cBalanceAfter = address(c).balance;
        uint callerBalanceAfter = nonOwner.balance;

        // The distinguishing general rule: when a non-owner (here any external caller) triggers withdrawAll
        // it must not reduce the contract's balance (i.e., withdrawAll must only succeed for the owner).
        // We express that as: if the external low-level call from this contract did not succeed (reverted),
        // then the contract balance after equals balance before. This holds for original P (non-owner call reverts),
        // but breaks for mutant M (non-owner call succeeds and decreases contract balance).
        assert((!success) || (cBalanceAfter == cBalanceBefore && callerBalanceAfter == callerBalanceBefore));
    }

    // allow this contract to receive Ether for the deposit
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // call withdrawAll as the provided caller by using low-level call to set msg.sender
        // We must not change c via any other calls here; perform the call but capture whether it reverted.
        // Use abi.encodeWithSignature to call withdrawAll() on c from this contract on behalf of caller
        // Note: cannot change msg.sender, so instead we model the property in terms of whether the call from this contract reverts
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // General rule: if the caller (msg.sender of this test) is not the contract's owner, withdrawAll must revert.
        // We cannot read c.owner() directly? owner is public in C, so we can.
        address owner = c.owner();
        // If this test's caller (the EOA that called this run) is not the owner, then the call we made should have reverted.
        assert((msg.sender == owner) || reverted);
    }
    receive() external payable { }
}

