contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // Tightened precondition: require the caller is not the owner, the contract
        // balance is nonzero, and the owner's address is not equal to msg.sender (observed via c.owner())
        // Additionally require that the owner is a valid non-zero address different from msg.sender
        // and that the caller's address is not equal to the contract address (to exclude edge cases
        // where msg.sender equals the contract itself or special symbolic values shown by the counterexample).
        require(msg.sender != c.owner() && address(c).balance > 0 && c.owner() != address(0) && msg.sender != address(this));
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // For all non-owners, withdrawAll must revert on the original contract
        assert(reverted == true);
    }
    receive() external payable { }
}

