import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to fund the contract and the owner actor (must be the deploying owner)
    function testFuzz_property(uint256 amount) public {
        // keep amount in a reasonable range (not too large to avoid overflow in vm.deal)
        amount = bound(amount, 0, 1 ether);

        // The reference contract sets owner = msg.sender in constructor (setUp deploys c as this test contract)
        // So the owner is this test contract's address. We will act as this test contract to call withdrawAll.

        // Fund the contract from some external EOA so that the contract has balance to withdraw.
        address funder = address(0xBEEF);
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("0x");
        require(sent, "funding failed");

        // Record owner (this contract) balance before withdrawAll
        uint256 ownerBefore = address(this).balance;
        uint256 contractBefore = address(c).balance;

        // Owner (this contract) calls withdrawAll
        // no vm.prank needed because c was deployed by this test contract so it is owner
        c.withdrawAll();

        // Exactly one assertion: owner balance increased by contractBefore (all funds sent to owner)
        // This property holds for the reference for all inputs; the mutant that sends to a hardcoded non-owner
        // address will cause this assertion to fail for inputs with contractBefore > 0
        assertTrue(address(this).balance == ownerBefore + contractBefore);
    }
}

