pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: the deposit amount and an arbitrary caller address (owner will be c's deployer)
    function testFuzz_property(uint256 depositAmount, address caller) public {
        // admissible domain: depositAmount should be within a reasonable range and positive
        // bound keeps it wide but avoids overflow for vm.deal
        depositAmount = bound(depositAmount, 0, 1 ether);
        vm.assume(depositAmount > 0);

        // c was deployed in setUp by this contract (this contract is the owner)
        address owner = address(this);

        // Fund the caller so they can send Ether to c if needed (we'll use owner to send funds)
        vm.deal(owner, depositAmount);

        // Owner sends depositAmount to c via fallback (simple transfer)
        // must use call with value so fallback() increments depositsCount and balance increases
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "funding failed");

        // record balances before withdrawAll
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // owner calls withdrawAll (this contract is owner by deployment)
        // Use try/catch to capture revert behavior if any implementation differs
        bool ok;
        try c.withdrawAll{ }() {
            ok = true;
        } catch {
            ok = false;
        }

        // After successful withdrawAll on reference, owner balance must have increased by contractBalanceBefore
        // We assert that if the call succeeded, ownerBalanceAfter == ownerBalanceBefore + contractBalanceBefore
        // (this reads c only via its behavior through balances and call result)
        if (ok) {
            uint256 ownerBalanceAfter = owner.balance;
            assertTrue(ownerBalanceAfter == ownerBalanceBefore + contractBalanceBefore);
        } else {
            // If call reverted, the reference contract never reverts on this scenario (owner calling withdrawAll after funding)
            // So a revert indicates the mutant; to ensure the test still distinguishes, assert false so that reference passes for all admissible inputs
            assertTrue(false);
        }
    }
}

