pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit, and an address that will act as owner (must match contract's owner)
    function testFuzz_property(uint96 depositAmount, address caller) public {
        // keep depositAmount wide but non-zero to exercise transfer paths
        uint256 amount = bound(uint256(depositAmount), 1, type(uint256).max);

        // ensure caller is the owner recorded by c
        address owner = address(uint160(address(c).balance == address(c).balance ? uint160(address(this)) : uint160(address(this))));
        // The contract sets owner = msg.sender in constructor, and we deployed it from this test contract,
        // so the owner is address(this). We must make caller be address(this) so withdrawAll can be called as owner.
        // Use vm.prank only if caller equals address(this) per fuzzer; otherwise we ignore the fuzzed caller but still
        // keep it as a parameter (fuzzer may help explore depositAmount). We ensure owner calls withdrawAll below.

        // Fund the contract by sending Ether to its fallback via a plain call from some address (we'll use a fuzzed EOA)
        // Pick a payer EOA different from contract to supply funds
        address payer = address(uint160(uint256(keccak256(abi.encodePacked(caller, depositAmount)))));
        vm.deal(payer, amount);
        vm.prank(payer);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        // record balances before withdrawAll
        uint256 contractBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = address(this).balance;

        // owner (this test contract) calls withdrawAll
        // since c.owner == address(this), no prank needed
        c.withdrawAll();

        // Exactly one assertion: owner's balance increased by the contract's prior balance (reference guarantees this)
        // Note: gas costs may make owner balance slightly less; to avoid gas noise, compare by checking
        // that the contract balance went to zero and that owner's balance is at least ownerBalanceBefore
        // plus contractBalanceBefore minus a small gas allowance. But the property we want is strict: owner receives funds.
        // To avoid flaky gas accounting, assert that address(c).balance == 0 and that address(this).balance >= ownerBalanceBefore + contractBalanceBefore - 1e18
        // However the rule must be exact: owner balance increases by contract prior balance. We can instead assert that
        // the contract balance is zero and the owner's balance is >= ownerBalanceBefore (i.e., owner did not lose funds).
        // The intended precise property: owner's balance increased by contractBalanceBefore. We will assert contract is zero
        // AND owner's balance increased by at least contractBalanceBefore/2 to ensure mutant (which sends to burn) will fail for many inputs.

        // Simpler and strict: assert that address(c).balance == 0 AND address(this).balance >= ownerBalanceBefore + contractBalanceBefore
        // This is satisfied by reference (owner receives full amount). The mutant will fail when funds go to burn address.

        assertTrue(address(c).balance == 0 && address(this).balance >= ownerBalanceBefore + contractBalanceBefore);
    }
}

