pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to fund contract, and whether owner is a reverting contract
    function testFuzz_property(uint256 amount, bool useReverter) public {
        // keep amount in a reasonable range but wide
        amount = bound(amount, 0, 1e18);

        // fund the contract so withdrawAll has balance to send
        address funder = address(0xBEEF);
        vm.deal(funder, amount);
        vm.prank(funder);
        // send funds to contract via plain call to fallback
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        // deploy either a normal recipient or a reverter that will revert on receive
        address recipient;
        if (useReverter) {
            Reverter r = new Reverter();
            recipient = address(r);
        } else {
            Recipient r = new Recipient();
            recipient = address(r);
        }

        // make recipient the owner by deploying a new instance of C? The contract sets owner to msg.sender at construction.
        // To set c.owner to our recipient, we must deploy a fresh C from that recipient. So deploy a proxy-like flow:
        // Instead, we simulate ownership by calling withdrawAll as the owner: we need msg.sender == owner.
        // The c was constructed with this test contract as owner (msg.sender in setUp). To test behavior when owner is an external contract,
        // we will deploy a new C from the recipient and test on that instance. Create new instance from recipient by using vm.prank.

        vm.stopPrank();
        // deploy a fresh contract d as if deployed by recipient so its owner is recipient
        C d;
        vm.prank(recipient);
        d = new C();

        // fund d
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool s2, ) = address(d).call{value: amount}("");
        require(s2);

        // Now call withdrawAll as the owner (recipient). For a failing recipient, call should revert on the reference because withdraw calls target's fallback which reverts.
        bool ok;
        vm.prank(recipient);
        try d.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any amount and choice, the reference implementation (which routes through withdraw and thus its external call can revert)
        // will revert when the owner is a contract whose fallback reverts; the mutant doing direct transfer to msg.sender would not revert in that case.
        // We therefore assert that when owner is a Reverter, withdrawAll fails (ok == false); and when owner is a normal recipient, it succeeds.
        // This single assert observes d (a public contract) via the try/catch result.
        if (useReverter) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

contract Recipient {
    // accept Ether
    receive() external payable {}
}

