pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: amount to fund C with before withdrawAll is called.
    // We also fuzz an extra uint to ensure fuzzer explores space; but only one is required.
    function testFuzz_property(uint256 seedAmount) public {
        // Keep domain wide but non-zero so there's value to transfer; allow many values.
        uint256 amount = bound(seedAmount, 1, 1 ether);

        // Deploy an adversarial owner contract that always reverts on receive/fallback
        RevertingOwner attacker = new RevertingOwner();

        // Fund the contract c with `amount` so withdrawAll will attempt to transfer that balance
        // Use an EOA (this) to send funds to c
        vm.deal(address(this), amount);
        c.sendMoney{value: amount}(address(c), amount, ""); // deposit via fallback to increment depositsCount

        // Now change owner of c to the attacker by directly interacting with storage is disallowed.
        // But owner is set at construction to msg.sender; we created c in setUp(), so owner is this test contract.
        // To make attacker the msg.sender for withdrawAll, we must call withdrawAll from attacker. We'll have attacker call c.withdrawAll().

        // Fund attacker so it can be owner caller and receive potential refunds — not strictly needed but safe
        vm.deal(address(attacker), 1 ether);

        // The general rule: when the withdrawAll triggers an external failing transfer to msg.sender (attacker that reverts on receive),
        // the good contract's withdrawAll should propagate the revert (i.e., the call should revert), whereas the mutant may behave differently.
        // We assert that calling withdrawAll from the reverting attacker DOES revert on the reference implementation.

        bool ok;
        try attacker.callWithdrawAll(c) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: reference contract (deployed as c) should revert when a reverting owner calls withdrawAll.
        // This reads c's behavior via the observable result of the external call.
        assertTrue(!ok);
    }
}

// Adversarial helper: owner contract that reverts on any receive or fallback, and can call c.withdrawAll()
contract RevertingOwner {
    // Called by test to invoke c.withdrawAll() as this contract
    function callWithdrawAll(C target) external {
        target.withdrawAll();
    }
    // Revert on receiving Ether
    receive() external payable {
        revert("no funds");
    }
    fallback() external payable {
        revert("no funds");
    }
}

