pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the deposit amount and the owner-depositing account
    function testFuzz_property(uint256 amount, address depositor) public {
        // keep depositor non-zero and amount in a reasonable range
        vm.assume(depositor != address(0));
        uint256 bounded = bound(amount, 0, 1 ether);

        // deploy a reverting owner contract and make it the owner by recreating C with that owner
        RevertingOwner ro = new RevertingOwner();
        // We need c to be owned by ro. The C contract sets owner = msg.sender on construction.
        // So deploy a fresh C owned by ro instead of the one from setUp.
        c = C(address(new COwnedBy{salt: 0}(address(ro))));

        // Fund the contract c so withdrawAll has something to send
        vm.deal(address(this), bounded);
        // deposit into c by calling sendMoney as owner (ro). We need to have ro call sendMoney; ro is a contract
        // and onlyOwner modifier requires msg.sender == owner, and owner is ro, so ro must call.
        // Let ro perform a deposit by invoking sendMoney on c. ro will call without reverting for this helper call.
        // Provide the depositor some ETH to forward through ro into c fallback
        vm.deal(address(ro), bounded);
        // Have ro call sendMoney on c to deposit bounded funds into target (we target c itself so that its fallback increments depositsCount)
        // ro will execute the call as its own msg.sender, satisfying onlyOwner
        ro.callSendMoney{value: bounded}(address(c), bounded, "");

        // Now c has balance bounded (or 0 if bounded==0). Calling withdrawAll should attempt to forward funds to msg.sender (ro)
        // For the reference contract, withdrawAll calls withdraw which uses call and so the failing fallback of ro will revert; we detect this via try/catch.
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for ANY bounded deposit amount and depositor, calling withdrawAll with owner that reverts
        // must revert on the correct contract. The mutant that does a direct transfer may not revert. We assert that the call reverted.
        assertTrue(!ok);
    }
}

// Helper that reverts on receiving Ether
contract RevertingOwner {
    // accept calls but revert on any Ether receipt
    fallback() external payable {
        revert("no receive");
    }
    receive() external payable {
        revert("no receive");
    }

    // helper to call c.sendMoney as owner; must be able to send value
    function callSendMoney(address _c, uint256 _value, uint256 sendValue, bytes memory _data) public payable {
        C(_c).sendMoney{value: sendValue}(address(_c), _value, _data);
    }
}

// Minimal factory to deploy C with a specific owner (by making constructor caller be the desired owner)
// We cannot change the original C source, so we deploy a tiny contract that in its constructor deploys C using the desired owner as msg.sender
contract COwnedBy {
    constructor(address owner) {
        // deploy a new C with msg.sender = this contract; we need owner to be the C.owner, so instead have owner be the msg.sender by creating a call from owner.
        // Achieve this by having the specified owner call this constructor via CREATE2 and then in its context deploy C. But simpler: we use a minimal delegate: the provided owner cannot be msg.sender for C here.
        // Workaround: deploy a helper Deployer contract from the desired owner which then constructs C. To keep file shape minimal, we instead revert if used incorrectly.
        // Actually we cannot make owner be msg.sender for C without that owner calling; thus to satisfy the test we instead deploy C and then set it to be owned by 'owner' by having owner be the deployer in setUp. To keep shape, we deploy C normally; tests above redeploy c via this path so owner==address(this) which won't match RevertingOwner. To correct: instead we will deploy C via a call from owner by using a low-level call to a contract owned by owner that performs new C().
        // Simpler approach: create a small Creator contract that when called by 'owner' deploys C and returns its address. But respecting constraints, keep minimal: revert here.
        revert("Use factory pattern externally");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the deposit amount and decide whether the owner-contract will revert
    function testFuzz_property(uint256 depositAmount, bool ownerWillRevert) public {
        // keep deposit amount in a sensible range but wide
        depositAmount = bound(depositAmount, 0, 1 ether);

        // Deploy an adversarial owner contract whose receive/fallback either reverts or accepts
        AdversarialOwner adv = new AdversarialOwner(ownerWillRevert);

        // Make adv the owner by deploying a fresh C with msg.sender as adv is not allowed per constraints
        // Instead, we simulate owner by transferring ownership: since C sets owner as deployer and no setter exists,
        // we need to interact as adv being msg.sender when calling withdrawAll. So we impersonate adv via vm.prank.

        // fund C with depositAmount so withdrawAll will attempt to send funds to msg.sender (the owner)
        vm.deal(address(this), depositAmount);
        payable(address(c)).transfer(depositAmount);

        // Now call withdrawAll as if from the adversarial owner. The reference implementation's withdrawAll
        // calls withdraw which performs a low-level call to msg.sender; if that call reverts, the whole withdrawAll should revert.
        // We detect if withdrawAll reverts by try/catch and set ok accordingly.
        bool ok;
        vm.prank(address(adv));
        try c.withdrawAll{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule to assert: if the adversarial owner contract reverts on receive/fallback and the contract has a
        // non-zero balance, then the reference C should cause withdrawAll to revert (ok == false). This is the property
        // that holds for the reference but is violated by the mutant for some inputs.
        if (ownerWillRevert && depositAmount > 0) {
            assertTrue(!ok);
        } else {
            // if owner does not revert or no funds, withdrawAll should not revert
            assertTrue(ok);
        }
    }
}

// Minimal adversarial owner: reverts on receive/fallback when configured
contract AdversarialOwner {
    bool public doRevert;
    constructor(bool _doRevert) payable { doRevert = _doRevert; }
    receive() external payable {
        if (doRevert) revert("receive revert");
    }
    fallback() external payable {
        if (doRevert) revert("fallback revert");
    }
}

