pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzz parameters: attacker (non-owner) and an amount to send from c to the callee
    function testFuzz_property(address attacker, uint256 amount) public {
        // keep attacker non-zero and not the deployer (owner)
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(this));
        // bound amount to reasonable range so we can fund c and the callee
        amount = bound(amount, 0, 1 ether);

        // Deploy an adversarial callee that always reverts on fallback
        Reverter rev = new Reverter();

        // Fund contract c so sendMoney has balance to attempt sending
        vm.deal(address(c), 1 ether);

        // Ensure attacker has ETH to pay for tx
        vm.deal(attacker, 1 ether);

        // The general observable we check: after calling sendMoney targeting a reverting callee,
        // the call should revert when executed by non-owner on the buggy mutant but in the
        // reference contract only the owner can call sendMoney so non-owner cannot change c state.
        // We simulate a non-owner trying to call sendMoney; capture whether the external call succeeded

        bool ok;
        // run as attacker (non-owner)
        vm.prank(attacker);
        try c.sendMoney(address(rev), amount, "0x") {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract: only owner can call sendMoney, so any non-owner call should revert (ok==false)
        // This is the universal property: for all attacker addresses and amounts, a non-owner calling sendMoney
        // will not succeed (ok == false) on the correct contract. The mutant removing the onlyOwner check
        // allows some non-owner calls to succeed (ok == true) for some inputs and thus breaks this rule.
        assertTrue(!ok);
    }
}

// adversarial callee that reverts on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

